\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,mathtools}
\usepackage{microtype}
\usepackage{hyperref}
\usepackage{enumitem}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{remark}[theorem]{Remark}
\newtheorem{example}[theorem]{Example}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\title{Pair-to-Edge Thresholds and a Kruskal--Katona Bridge\\from Triangles to Edges}
\author{Aristotle}
\date{July 15, 2026}

\begin{document}
\maketitle

\begin{abstract}
For a finite simple graph with $m>0$ edges and $n$ non-isolated vertices, we study the pair-to-edge ratio
\[
T(n,m)=\frac{\binom n2}{m}.
\]
The universal edge bound and the handshake identity give the sharp interval $1\leq T(n,m)\leq n-1$. Consequently every genuine probability $p<1$ automatically satisfies $p<T(n,m)$; equivalently, $pm<\binom n2$. Thus the bare threshold inequality is non-discriminating in the usual strict probability range. We then connect graph clique counts to shadows of uniform set families. The vertex sets of triangles form a $3$-uniform family, and its $2$-shadow is contained in the edge set. The Kruskal--Katona theorem therefore implies that, for $3\leq k\leq n$, at least $\binom k3$ triangles force at least $\binom k2$ edges. We discuss sharpness, algorithms, applications, and extensions.
\end{abstract}

\section{Introduction}
A finite simple graph records pairwise interaction without loops or repeated edges. Its basic statistic is the number of edges, while triangles record higher-order clustering. This paper develops two complementary uses of the count $\binom n2$.

First, $\binom n2/m$ is the reciprocal of edge density. A condition
\[
p<\frac{\binom n2}{m}
\]
may appear to impose a substantive upper bound on a probability. In fact, simplicity forces $m\leq\binom n2$, so the right-hand side is at least one. The condition is automatic whenever $p<1$. If all $n$ vertices are non-isolated, the handshake identity also gives the sharp upper endpoint $n-1$.

Second, a triangle is a three-element vertex set all of whose pairs are edges. Passing from triangles to constituent pairs is precisely the shadow operation from extremal set theory. Kruskal--Katona lower-bounds the shadow of a uniform family and yields a sharp graph theorem: $\binom k3$ triangles require at least $\binom k2$ edges.

Both arguments count distinct unordered pairs rather than incidences. In the first, edges are compared with all possible pairs. In the second, edges are compared with pairs supporting a family of triples. The threshold result exposes a weak hypothesis; the shadow result gives a genuine extremal obstruction.

\section{Definitions}
\begin{definition}
A \emph{finite simple graph} is a pair $G=(V,E)$ in which $V$ is finite and $E$ is a set of unordered two-element subsets of $V$. Write $n=|V|$ and $m=|E|$. The degree $\deg(v)$ is the number of edges containing $v$. A vertex is isolated if $\deg(v)=0$.
\end{definition}

A triangle is a three-element set $B\subseteq V$ such that each two-element subset of $B$ lies in $E$. More generally, an $r$-clique is an $r$-element set inducing a complete graph. The complete graph contains all $\binom n2$ possible edges. A matching has no two edges sharing a vertex; a perfect matching on even $n$ has $n/2$ edges and no isolated vertices.

\begin{definition}
For $m>0$, the \emph{pair-to-edge threshold} is
\[
T(n,m)=\frac{\binom n2}{m}.
\]
For $n\geq2$, the edge density is $\rho(G)=m/\binom n2$, so $T=1/\rho$.
\end{definition}

\begin{definition}
A family $\mathcal F$ of subsets of $V$ is $r$-uniform if every member has size $r$. Its lower shadow is
\[
\partial\mathcal F=\{A\subseteq V:|A|=r-1\text{ and }A\subseteq B\text{ for some }B\in\mathcal F\}.
\]
If $\mathcal T(G)$ is the triangle family, then it is $3$-uniform and $\partial\mathcal T(G)$ is a family of pairs.
\end{definition}

\section{The pair-to-edge threshold}
\begin{lemma}[Pair formula]
For every nonnegative integer $n$, as an identity over the reals,
\[
2\binom n2=n(n-1).
\]
\end{lemma}
\begin{proof}
Count ordered pairs of distinct elements. There are $n(n-1)$, while each unordered pair gives exactly two orderings.
\end{proof}

\begin{lemma}[Pair positivity]
If $n\geq2$, then $\binom n2>0$.
\end{lemma}
\begin{proof}
The pair formula expresses twice the coefficient as the product of the positive numbers $n$ and $n-1$.
\end{proof}

\begin{lemma}[Universal edge bound]
Every finite simple graph on $n$ vertices with $m$ edges satisfies $m\leq\binom n2$.
\end{lemma}
\begin{proof}
Each edge is one of the $\binom n2$ unordered pairs of distinct vertices, and no edge is repeated.
\end{proof}

\begin{theorem}[Threshold lower bound]
If $m>0$ and $m\leq\binom n2$, then $1\leq T(n,m)$. In particular, this holds for every nonempty simple graph.
\end{theorem}
\begin{proof}
Divide $m\leq\binom n2$ by the positive number $m$.
\end{proof}

\begin{theorem}[Strict edge-budget equivalence]
For $m>0$ and real $p$,
\[
p<T(n,m)\quad\Longleftrightarrow\quad pm<\binom n2.
\]
\end{theorem}
\begin{proof}
Multiplication by the positive denominator $m$ preserves strict inequalities.
\end{proof}

\begin{corollary}[Contrarian probability conclusion]
For every nonempty finite simple graph and every real $p<1$, one has $p<T(n,m)$.
\end{corollary}
\begin{proof}
The threshold is at least one, so $p<1\leq T(n,m)$. Equivalently, $pm<m\leq\binom n2$.
\end{proof}

Thus the threshold condition alone distinguishes neither sparse from dense graphs nor connected from disconnected graphs within the ordinary strict probability range.

\section{Non-isolated vertices and the upper endpoint}
\begin{lemma}[Handshake identity]
Every finite simple graph satisfies
\[
\sum_{v\in V}\deg(v)=2m.
\]
\end{lemma}
\begin{proof}
Count vertex-edge incidences. Summing by vertices gives the left side; every edge contributes its two endpoints to the right side.
\end{proof}

\begin{theorem}[No-isolated-vertices bound]
If every one of the $n$ vertices is non-isolated, then $n\leq2m$.
\end{theorem}
\begin{proof}
Every degree is at least one, whence
\[
n=\sum_{v\in V}1\leq\sum_{v\in V}\deg(v)=2m.
\]
\end{proof}

\begin{theorem}[Sharp threshold interval]
Every nonempty finite simple graph on $n$ non-isolated vertices and with $m$ edges satisfies
\[
1\leq T(n,m)\leq n-1.
\]
Both endpoints are sharp.
\end{theorem}
\begin{proof}
The lower bound is universal. For the upper bound, $2m\geq n$ and the pair formula give
\[
T(n,m)=\frac{n(n-1)}{2m}\leq\frac{n(n-1)}n=n-1.
\]
The complete graph has $m=\binom n2$ and $T=1$. For even $n$, a perfect matching has $m=n/2$ and $T=n-1$.
\end{proof}

For odd $n$, the upper endpoint need not be attained, since a graph in which every vertex has degree one cannot have odd order. Sharpness here means that the uniform bound cannot be reduced over all admissible $n$.

\section{Triangles, shadows, and edges}
\begin{lemma}[Triangle uniformity]
For every finite simple graph $G$, the family $\mathcal T(G)$ of triangular vertex sets is $3$-uniform.
\end{lemma}
\begin{proof}
This is immediate from the definition of a triangle as a set of exactly three vertices satisfying the clique condition.
\end{proof}

\begin{lemma}[Shadow-to-edge lemma]
For every finite simple graph $G$,
\[
\partial\mathcal T(G)\subseteq E(G).
\]
\end{lemma}
\begin{proof}
A member of the shadow is a two-element subset of a triangle. Every pair of vertices in a triangle is adjacent, so that pair is an edge.
\end{proof}

\begin{theorem}[Kruskal--Katona shadow bound, binomial case]
Let $\mathcal F$ be a $3$-uniform family on an $n$-element ground set. If $3\leq k\leq n$ and
\[
|\mathcal F|\geq\binom k3,
\]
then
\[
|\partial\mathcal F|\geq\binom k2.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The Kruskal--Katona theorem says that initial segments in colexicographic order minimize the lower shadow among uniform families of fixed size. At size $\binom k3$, the extremal family is all triples from a fixed $k$-element set. Its shadow is all pairs from that set, of size $\binom k2$. Enlarging a family cannot decrease its shadow.
\end{proof}

\begin{theorem}[Triangle-to-edge theorem]
Let $G$ be a finite simple graph on $n$ vertices. If $3\leq k\leq n$ and
\[
|\mathcal T(G)|\geq\binom k3,
\]
then
\[
|E(G)|\geq\binom k2.
\]
\end{theorem}
\begin{proof}
The triangle family is $3$-uniform, so the shadow theorem gives $|\partial\mathcal T(G)|\geq\binom k2$. Since the shadow is contained in the edge set,
\[
\binom k2\leq|\partial\mathcal T(G)|\leq|E(G)|.
\]
\end{proof}

A $2$-clique is exactly a two-element adjacent vertex set, hence the family of $2$-cliques and the graph's edge set have equal cardinality. The theorem is sharp: a complete graph on $k$ vertices has exactly $\binom k3$ triangles and $\binom k2$ edges. Additional isolated vertices preserve equality while increasing the ambient order.

\section{Algorithms and numerical diagnostics}
The threshold can be tested exactly. If $p=a/b$ with $b>0$, then
\[
p<T(n,m)\quad\Longleftrightarrow\quad am<b\binom n2.
\]
Thus no floating-point arithmetic is needed. Once the inputs are supplied, only a constant number of integer operations are required; bit complexity is governed by integer multiplication.

For an edge-list graph, degrees can be accumulated in $O(n+m)$ time. Checking that every degree is positive permits the sharp interval certificate $1\leq T\leq n-1$.

Given a triangle count $t$, the strongest integer consequence of the triangle-to-edge theorem is obtained by finding the largest $k\leq n$ satisfying $\binom k3\leq t$. Monotonicity for $k\geq3$ permits binary search using $O(\log n)$ comparisons, after which $\binom k2$ is a certified edge lower bound.

For small $n$, exhaustive illustration is possible. Enumerate all $2^{\binom n2}$ subsets of possible edges and test each of the $\binom n3$ triples. This costs
\[
O\!\left(2^{\binom n2}\binom n3\right),
\]
so it is pedagogical rather than scalable.

\section{Examples}
\begin{example}
A complete graph has $m=\binom n2$ and $T=1$. It also has $\binom n3$ triangles, and the triangle-to-edge theorem is exact with $k=n$.
\end{example}

\begin{example}
For even $n$, a perfect matching has $m=n/2$, no isolated vertices, no triangles, and $T=n-1$. It attains the opposite endpoint from the complete graph.
\end{example}

\begin{example}
Since $\binom53=10$ and $\binom52=10$, ten triangles force at least ten edges. Since $\binom63=20$ and $\binom62=15$, twenty triangles force at least fifteen edges.
\end{example}

\begin{example}
If $n=10$ and $m=15$, then $T=45/15=3$. Every probability $p<1$ lies below this threshold, illustrating that reciprocal density is not naturally probability-scaled.
\end{example}

\section{Applications and discussion}
Triangles model cohesion in social, biological, and information networks. The triangle-to-edge theorem gives a minimum pairwise infrastructure needed for a prescribed number of cohesive triples, regardless of overlap. The same statement applies to a $3$-uniform hypergraph of three-way observations: its pairwise projection is the shadow, and $\binom k3$ triples force $\binom k2$ distinct pairwise co-occurrences.

The inequalities also provide data checks. Reported values violating $m\leq\binom n2$, $n\leq2m$ under non-isolation, or the triangle-forced lower bound cannot describe the claimed graph. Such certificates use integer arithmetic and are easy to audit.

The threshold analysis warns against comparing a probability with reciprocal density. If a parameter should lie in $[0,1]$, the density $m/\binom n2$ is more naturally scaled. A nontrivial result based on $p<T(n,m)$ must add a meaningful conclusion and further structure, permit $p\geq1$, or assign $p$ a non-probabilistic interpretation.

A naive triangle incidence identity,
\[
3|\mathcal T(G)|=\sum_{e\in E(G)}\#\{\text{triangles containing }e\},
\]
does not itself give the sharp edge lower bound because one edge may support many triangles. Shadows remove multiplicity and ask exactly how many distinct pairs support the triples. The extremal configuration concentrates triples on a small vertex set: all triples on $k$ vertices use all $\binom k2$ pairs. Dispersing the triples cannot lower their shadow.

Isolated vertices play different roles in the two results. They do not affect the triangle implication, except through the harmless requirement $k\leq n$. In threshold analysis, however, counting isolated vertices would enlarge the possible-pair count without adding edges. Restricting to non-isolated vertices produces the meaningful upper endpoint.

\section{Future work}
The motivating threshold claim did not specify the consequence intended to follow from $p<T(n,m)$. A continuation should state that conclusion and test hypotheses such as connectedness, minimum degree, regularity, expansion, or a specified random-graph model. The present results show that the threshold alone cannot support a nontrivial structural conclusion for $p<1$.

The shadow bridge extends naturally to higher cliques. The family of $r$-cliques is $r$-uniform, and its lower shadow consists of $(r-1)$-cliques. Iterated shadows can relate large-clique counts directly to edge counts.

Stability is another direction. If a graph nearly attains the minimum edge count permitted by its number of triangles, its triangle-supporting subgraph should resemble a complete graph concentrated on roughly $k$ vertices. Quantitative stability would turn near-equality into structural information.

Algorithmically, triangle counts can be obtained without exhaustive triple enumeration by adjacency intersections, degeneracy orientations, or matrix multiplication. These counts can feed directly into shadow-based certificates. Random and pseudorandom graphs also invite comparison: in an Erd\H{o}s--R\'enyi graph with edge probability $q$, expected edge and triangle counts are $q\binom n2$ and $q^3\binom n3$. Their diffuse structure contrasts with the concentrated extremizers of Kruskal--Katona.

\section{Conclusion}
For a nonempty simple graph with $m$ edges and $n$ non-isolated vertices,
\[
1\leq\frac{\binom n2}{m}\leq n-1.
\]
The lower endpoint makes $p<\binom n2/m$ automatic for every $p<1$, while the upper endpoint follows from the handshake identity. At a deeper structural level, triangle sets form a $3$-uniform family whose shadow lies in the edge set, so
\[
|\mathcal T(G)|\geq\binom k3\quad\Longrightarrow\quad|E(G)|\geq\binom k2
\]
for $3\leq k\leq n$. The same count of unordered pairs thus exposes a vacuous threshold and supplies a sharp extremal constraint.

\end{document}

