from fractions import Fraction
from math import comb

def threshold(n: int, m: int) -> Fraction:
    if m <= 0 or m > comb(n, 2):
        raise ValueError("Require 0 < m <= C(n,2).")
    return Fraction(comb(n, 2), m)

for n, m in [(6, 15), (6, 3), (10, 15)]:
    value = threshold(n, m)
    print(f"n={n}, m={m}: T={value}, interval=[1,{n-1}]")

from math import comb

def forced_edges(k: int) -> tuple[int, int]:
    if k < 3:
        raise ValueError("k must be at least 3")
    return comb(k, 3), comb(k, 2)

for k in range(3, 11):
    triangles, edges = forced_edges(k)
    print(f"At least {triangles} triangles force at least {edges} edges.")

