from fractions import Fraction
from math import comb

def exact_threshold_certificate(n: int, m: int, p: Fraction) -> dict[str, object]:
    if n < 2 or not 0 < m <= comb(n, 2):
        raise ValueError("Inputs do not describe a nonempty simple graph pair budget.")
    pairs = comb(n, 2)
    return {
        "threshold": Fraction(pairs, m),
        "below_threshold": p.numerator * m < p.denominator * pairs,
        "automatic_below_one": p < 1,
    }

from math import comb

def triangle_shadow_bound(n: int, triangles: int) -> tuple[int, int]:
    if n < 3 or triangles < 0:
        raise ValueError("Require n >= 3 and triangles >= 0.")
    low, high = 3, n
    answer = 2
    while low <= high:
        mid = (low + high) // 2
        if comb(mid, 3) <= triangles:
            answer = mid
            low = mid + 1
        else:
            high = mid - 1
    return answer, comb(answer, 2)

from itertools import combinations
from typing import Iterable

Edge = tuple[int, int]

def graph_statistics(n: int, edges: Iterable[Edge]) -> tuple[list[int], int]:
    edge_set = {tuple(sorted(edge)) for edge in edges}
    if any(u == v or u < 0 or v >= n for u, v in edge_set):
        raise ValueError("Invalid simple-graph edge.")
    degree = [0] * n
    for u, v in edge_set:
        degree[u] += 1
        degree[v] += 1
    triangles = sum(
        (a, b) in edge_set and (a, c) in edge_set and (b, c) in edge_set
        for a, b, c in combinations(range(n), 3)
    )
    return degree, triangles

